'use strict';
let overview=null, filter='all';
const $=s=>document.querySelector(s), esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=0)=>v==null?'—':v.toLocaleString('id-ID',{maximumFractionDigits:d,minimumFractionDigits:d});
const pct=v=>v==null?'—':num(v*100,2)+'%';
const labels={green:'Sehat',amber:'Waspada',red:'Kritis',unknown:'Tidak tersedia'};
const dialog=$('#detail');function show(html){$('#detail-content').innerHTML=html;dialog.showModal();}$('.close').onclick=()=>dialog.close();
function rows(){ $('#app-rows').innerHTML=(overview?.applications||[]).filter(a=>filter==='all'||a.rag!=='green').map(a=>`<tr><td><button class="app-name" data-app="${esc(a.id)}">${esc(a.name)}<small>${esc(a.owner)}</small></button></td><td><span class="status ${a.liveUptime==null?'unknown':a.liveUptime>=100?'green':'red'}">${a.liveUptime==null?'—':a.liveUptime>=100?'Up':'Down'}</span></td><td><span class="status ${a.rag}">● ${labels[a.rag]}</span></td><td>${pct(a.uptimeMtd)}</td><td>${num(a.p95Ms)} ms</td><td>${pct(a.errorRate)}</td><td>${num(a.requestCount)}</td><td><button data-app="${esc(a.id)}" aria-label="Detail ${esc(a.name)}">↗</button></td></tr>`).join(''); }
function render(d){overview=d;document.body.classList.add('loaded');$('.demo').textContent=d.mode==='production'?'DATA PRODUKSI':'SIMULASI VIA API';const m=d.metrics,c=d.healthCounts;
$('.snapshot').textContent=(d.mode==='production'?'Agregasi produksi · ':'Agregasi simulasi · ')+new Date(d.generatedAt).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})+' WIB';
$('.summary strong').textContent=d.status==='partial'?'Sebagian data tidak tersedia':c.red||c.amber?'Layanan membutuhkan perhatian':'Seluruh layanan sehat';
$('.summary p').textContent=`${c.green} sehat · ${c.amber} waspada · ${c.red} kritis · ${c.unknown} tidak tersedia. ${d.mode==='production'?'Data dari koneksi produksi.':'Data dari adapter simulasi.'}`;
$('.health-count').innerHTML=Object.entries(c).map(([k,v])=>`<span><b class="${k}">${v}</b>${labels[k]}</span>`).join('');
$('#incident-jump').textContent=d.incidents===null?'Insiden tidak tersedia':`${d.incidents.length} insiden aktif ↗`;
const metrics=[['Overall service health',pct(m.healthRatio),'Aplikasi sehat / seluruh aplikasi'],['Availability / SLA',pct(m.availabilityMtd),'Kuma · MTD · target 99,90%'],['Response time p95',num(m.p95Ms)+' ms','SigNoz · global · 24 jam'],['Error rate',pct(m.errorRate),'Total HTTP 5xx / total request'],['Request volume',num(m.requestCount),'SigNoz · 24 jam']];
$('#metrics').innerHTML=metrics.map(x=>`<article class="metric"><div class="metric-title">${x[0]}</div><div class="metric-value">${x[1]}</div><div class="metric-foot">${x[2]}</div></article>`).join('');rows();
const trend=d.performanceTrend;
$('#performance-chart').innerHTML=trend?`<svg viewBox="0 0 750 125" preserveAspectRatio="none" role="img" aria-label="Tren simulasi 24 jam terakhir">${[20,65,110].map((y,i)=>`<line x1="38" x2="710" y1="${y}" y2="${y}" stroke="#283547"/><text x="0" y="${y}" fill="#8c9bae" font-size="9">${[1000,500,0][i]} ms</text><text x="714" y="${y}" fill="#8c9bae" font-size="9">${[2,1,0][i]}%</text>`).join('')}${[['p95Ms',1000,'#60dfbd'],['errorRate',.02,'#f08186']].map(([key,max,color])=>`<polyline points="${trend.map((v,i)=>`${38+i*29.1},${110-v[key]/max*90}`).join(' ')}" fill="none" stroke="${color}" stroke-width="2"/>`).join('')}</svg>`:'Data SigNoz tidak tersedia';
$('.chart-axis').innerHTML='<span>24 jam lalu</span><span>18 jam lalu</span><span>12 jam lalu</span><span>6 jam lalu</span><span>Sekarang</span>';
$('.analytics .source-label').textContent=d.mode==='production'?'Matomo · hari ini':'Matomo · 24 jam';$('footer .muted').textContent=d.mode==='production'?'— Mode produksi; indikator kosong belum tersedia.':'— Seluruh angka merupakan simulasi.';$('.chart-note').textContent=d.mode==='production'?'Tren belum dipetakan':'Tren simulasi · 24 jam terakhir';
$('#incidents').innerHTML=`<div class="panel-head"><h2>Insiden aktif</h2><span class="source-label">SigNoz</span></div>${d.incidents===null?'<p class="incident-note">Sumber insiden tidak tersedia</p>':d.incidents.map(i=>`<button class="incident" data-app="${esc(i.appId)}"><span class="severity">${esc(i.severity)}</span><div><strong>${esc(i.summary)}</strong><p>${esc(i.owner)} · ${esc(i.state)}</p><small>Mulai ${new Date(i.startedAt).toLocaleTimeString('id-ID',{timeZone:'Asia/Jakarta'})} WIB</small></div></button>`).join('')}`;
const a=d.analytics;
$('.analytics-values').innerHTML=a?(a.sites&&a.sites.length?`<table style="grid-column:1/-1;width:100%;border-collapse:collapse;font-size:13px"><thead><tr><th style="text-align:left;padding:4px 0">Site</th><th>Pengunjung unik</th><th>Page views</th><th>Bounce rate</th><th>Durasi sesi</th></tr></thead><tbody>${a.sites.map(s=>`<tr><td style="text-align:left;padding:6px 0">${esc(s.name||('Site '+s.siteId))}</td><td style="text-align:center">${num(s.uniqueVisitors)}</td><td style="text-align:center">${num(s.pageViews)}</td><td style="text-align:center">${s.bounceRate==null?'—':pct(s.bounceRate)}</td><td style="text-align:center">${s.averageSessionSeconds==null?'—':num(s.averageSessionSeconds)+' detik'}</td></tr>`).join('')}</tbody></table>`:`<div><span>Pengunjung unik</span><strong>${num(a.uniqueVisitors)}</strong></div><div><span>Page views</span><strong>${num(a.pageViews)}</strong></div>`):'<p>Data Matomo tidak tersedia</p>';
$('#user-bars').innerHTML=a?(a.hourlyVisits||[]).map(v=>`<i style="height:${v/Math.max(...a.hourlyVisits)*100}%"></i>`).join(''):'';
$('.analytics-bottom').innerHTML=a?`<span>Bounce rate <b>${pct(a.bounceRate)}</b></span><span>Durasi sesi <b>${num(a.averageSessionSeconds)} detik</b></span>`:'—';
const b=d.business;
$('.business').innerHTML=`<div class="panel-head"><h2>Data</h2><span class="source-label">Superset</span></div><div style="padding:0 18px 14px">${b&&b.apps&&b.apps.length?b.apps.map((ap,i)=>`<div style="${i?'border-top:1px solid rgba(255,255,255,.06);':''}padding:10px 0"><div style="font-size:13px;font-weight:600;margin-bottom:6px">${esc(ap.name)}</div><div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px">${ap.kpis.map(k=>`<div><div style="font-size:11px;opacity:.65">${esc(k.label)}</div><div style="font-size:18px;font-weight:600;margin-top:2px">${k.value==null?'—':num(k.value)}</div></div>`).join('')}</div></div>`).join(''):'<p class="muted">Data Superset tidak tersedia</p>'}</div>`;
$('.source-help').textContent='API agregasi · '+d.mode;
}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));rows();});
const sourceLinks=()=>Object.values(OBS_CONFIG.sources).map(s=>`<a href="${esc(s.url+s.path)}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a>`).join('');
document.addEventListener('click',e=>{const app=e.target.closest('[data-app]'),source=e.target.closest('[data-source]');if(app){const a=overview.applications.find(a=>a.id===app.dataset.app);show(`<div class="eyebrow">RESPONS API</div><h2>${esc(a.name)}</h2><p>${esc(a.owner)} · ${labels[a.rag]}</p><dl><div><dt>Uptime MTD</dt><dd>${pct(a.uptimeMtd)}</dd></div><div><dt>p95</dt><dd>${num(a.p95Ms)} ms</dd></div><div><dt>Error rate</dt><dd>${pct(a.errorRate)}</dd></div><div><dt>Request 24 jam</dt><dd>${num(a.requestCount)}</dd></div></dl><p>Tautan sumber berikut masih placeholder.</p>${sourceLinks()}`);}if(source){const s=overview.sources[source.dataset.source];show(`<h2>${esc(OBS_CONFIG.sources[source.dataset.source].name)}</h2><p>Mode ${esc(overview.mode)} · ${esc(s.status)}</p><p>Waktu data: ${esc(s.observedAt)}</p><p>${esc(s.error?.message||(overview.mode==='production'?'Respons API produksi diterima. Waktu di bawah adalah waktu pengambilan, bukan jaminan freshness dataset.':'Belum terhubung ke platform produksi.'))}</p>${sourceLinks()}`);}});
$('#incident-jump').onclick=()=>show(`<h2>Insiden</h2>${overview?.incidents?overview.incidents.map(i=>`<p>${esc(i.severity)} · ${esc(i.summary)}<br>${esc(i.owner)} · ${esc(i.state)}</p>`).join(''):'<p>Data tidak tersedia</p>'}`);
$('#methodology').onclick=()=>show('<h2>Agregasi backend</h2><p>Health = aplikasi hijau / seluruh aplikasi; tidak dihitung jika ada status unknown. Availability = rerata uptime MTD. Error rate = total error / total request. p95 global berasal dari fixture kuantil, bukan rata-rata p95 aplikasi.</p><p>Hijau: uptime ≥99,90%, p95 &lt;500 ms, error &lt;0,50%. Merah jika down, uptime &lt;99,90%, p95 ≥1.000 ms atau error ≥2%. Kondisi lain kuning. Data gagal/kedaluwarsa menjadi unknown.</p><p>Mode sumber mengikuti konfigurasi backend. Polling 60 detik. Kredensial hanya di server. Insiden dan tren produksi belum dipetakan.</p>');
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{show('<p>Layar penuh tidak tersedia pada browser ini.</p>');}};
async function refresh(){try{const r=await fetch(OBS_CONFIG.summaryEndpoint,{signal:AbortSignal.timeout(30000),cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json();if(d.schemaVersion!=='1.0'||!Array.isArray(d.applications))throw Error('Format respons tidak valid');render(d);}catch(e){$('.source-help').textContent='API tidak tersedia';$('.summary strong').textContent='Koneksi backend gagal';$('.summary p').textContent=overview?'Data terakhir kedaluwarsa — bukan kondisi saat ini.':'Jalankan backend Python, lalu buka dashboard melalui alamat backend.';$('#metrics').innerHTML='<p>Data terkini tidak tersedia.</p>';$('#app-rows').innerHTML='';$('#performance-chart').innerHTML='Data tidak tersedia';$('.analytics-values').innerHTML='<p>Data tidak tersedia</p>';$('#user-bars').innerHTML='';$('.analytics-bottom').textContent='—';$('.business').innerHTML='<p class="incident-note">Data tidak tersedia</p>';$('#incidents').innerHTML='<p class="incident-note">Insiden tidak tersedia</p>';$('.health-count').textContent='Status tidak diketahui';$('#incident-jump').textContent='Insiden tidak tersedia';$('#source-links').innerHTML='';overview=null;}finally{setTimeout(refresh,60000);}}
$('.demo').textContent='SIMULASI VIA API';$('.performance-foot').textContent='Simulasi · target p95 < 500 ms · error rate < 0,50%';
function clock(){$('#clock').textContent=new Date().toLocaleTimeString('id-ID',{timeZone:'Asia/Jakarta',hour:'2-digit',minute:'2-digit'})+' WIB';}clock();setInterval(clock,30000);refresh();
